import {configSection,today} from '../core/business.js?v=20261111-v15a';
import {orderPaymentPlan,paymentConfirmation} from '../core/order-payment.js?v=20261111-v15a';

export function install(ctx){
 function orderPaymentDialog(id,transition=null,providedPlan=null){
  const q=ctx.quotes.find(q=>q.id===id);if(!q)return;
  const change=transition||{p_quote:id,p_stage:q.stage,p_delivery:q.delivery_date,p_production:q.production||{},p_note:'',p_expected:q.updated_at};
  const plan=providedPlan||orderPaymentPlan(ctx,q,change.p_stage,{manual:true});if(!plan)return;
  const cfg=configSection(ctx.settings,'budget'),request=crypto.randomUUID();
  const canRecord=ctx.can('finance','create')&&ctx.can('finance','settle');
  const accounts=(ctx.business?.accounts||[]).filter(a=>a.active),methods=configSection(ctx.settings,'finance').payment_methods;
  const stageLabel=configSection(ctx.settings,'production').stages.find(s=>s.key===change.p_stage)?.label||change.p_stage;
  const needsAnswer=plan.newAmount>0;
  const d=ctx.modal(plan.final?'Finalizar pedido e emitir recibo':transition?'Confirmar andamento e recebimento':'Recebimento e recibo',`<form id="order-payment-form"><p><strong>Pedido #${ctx.esc(ctx.quoteRef(q))} · ${ctx.esc(q.client_snapshot.name)}</strong></p><p>${transition?'Próxima etapa: <strong>'+ctx.esc(stageLabel)+'</strong>. ':''}Já recebido: <strong>${ctx.money(plan.paid)}</strong> · Saldo: <strong>${ctx.money(plan.balance)}</strong>.</p>${needsAnswer?`<label class="field">${plan.isBalance?'O cliente já pagou o saldo?':'Você já recebeu a entrada do cliente?'}<select name="received" required><option value="">Selecione uma opção</option>${canRecord?'<option value="yes">Sim, já recebi</option>':''}<option value="no">Ainda não recebi</option></select></label>${!canRecord?'<p class="note">Seu acesso não permite registrar recebimentos. Solicite a baixa a um usuário autorizado.</p>':''}`:`<input type="hidden" name="received" value="no"><p class="note">O pagamento já está registrado. Vamos aproveitar o recebimento existente, sem nova baixa.</p>`}<div id="order-payment-fields" hidden><div class="grid2">${ctx.field('Valor recebido agora (R$)','amount','number',plan.newAmount||'','min="0.01" max="'+plan.balance+'" step="0.01"')}<label class="field">Conta que recebeu<select name="account"><option value="">Selecione a conta</option>${accounts.map(a=>`<option value="${ctx.esc(a.id)}">${ctx.esc(a.name)}</option>`).join('')}</select></label>${ctx.field('Data do recebimento','paid_on','date',today())}<label class="field">Forma de pagamento<select name="method"><option value="">Selecione a forma</option>${methods.map(m=>`<option value="${ctx.esc(m)}">${ctx.esc(m)}</option>`).join('')}</select></label></div>${!accounts.length?'<p class="error">Cadastre uma conta ativa em Configurações → Financeiro.</p>':''}<p class="muted helper">Informe apenas um pagamento já recebido e ainda não lançado no Financeiro.</p></div><p id="order-payment-summary" class="note" role="status"></p>${plan.final?'':'<details><summary>Mensagem no recibo</summary>'}<label class="field" ${plan.final?'hidden':''}>Texto para o cliente<textarea name="message" maxlength="5000">${ctx.esc(plan.final?cfg.final_receipt_message||'':cfg.receipt_message||'')}</textarea></label>${plan.final?'':'</details>'}<p class="error" role="alert" id="order-payment-error"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button type="submit" class="primary">Confirmar</button></div></form>`,{wide:true});
  const form=d.querySelector('form'),button=form.querySelector('[type="submit"]');
  function update(){const yes=form.elements.received.value==='yes';d.querySelector('#order-payment-fields').hidden=!yes;for(const name of ['amount','account','paid_on','method']){form.elements[name].disabled=!yes;form.elements[name].required=yes}button.textContent=yes?(plan.final?'Receber saldo, finalizar e abrir recibo':transition?'Registrar, avançar e abrir recibo':'Registrar e abrir recibo'):plan.final?'Finalizar e abrir recibo':plan.available>0?'Avançar e abrir recibo':transition?'Salvar andamento':'Abrir recibo existente';d.querySelector('#order-payment-summary').textContent=yes?'Uma confirmação registra a baixa, atualiza o pedido e prepara o recibo.':plan.final&&plan.balance>0?'Sem a quitação, o pedido continua na etapa atual. Nenhum recebimento será criado.':needsAnswer?'Sem confirmação de recebimento, não haverá baixa. As regras de entrada e aprovação continuam valendo.':'Nenhum pagamento será duplicado.';}
  form.elements.received.onchange=update;update();let completed=false,result=null;
  form.onsubmit=async e=>{e.preventDefault();button.disabled=true;try{
   if(!completed){const values=Object.fromEntries(new FormData(form)),payment=paymentConfirmation(plan,values);result=await ctx.rpc('advance_order_with_payment',{...change,...payment,p_request:request});completed=true;}
   await ctx.load();d.close();
   if(result.receipt){if(await ctx.showReceipt(result.receipt)!==false){if(result.ready&&cfg.ready_message_auto!==false)ctx.readyMessageDialog(id);ctx.toast(plan.final?'Pedido finalizado e recibo de quitação emitido.':'Recebimento conferido e recibo pronto para compartilhar.');return}ctx.render('workflow');ctx.receiptListDialog(id);return;}
   ctx.render('workflow');if(result.ready&&cfg.ready_message_auto!==false)ctx.readyMessageDialog(id);
   ctx.toast('Andamento atualizado. Nenhum novo recebimento registrado.');
  }catch(err){d.querySelector('#order-payment-error').textContent=err.message;button.disabled=false;}};
 }
 Object.assign(ctx,{orderPaymentDialog});
}
